/*
 * fwtransmute.c - TK-x4x firmware normalizer and revision converter
 *
 * Linked into TK-x4x Toolkit; firmware images are processed in memory and
 * written only through the Toolkit's explicitly selected save/write actions.
 *
 * Supported input revisions:
 *     TK-940/941 B5EC, 2CCA, 8E9D, AB00; TK-840 9306
 *
 * Conversion output:
 *     verified stock AB00 (TK-940/941) or verified stock 8355 (TK-840)
 *
 * Operation:
 *   - Input images must be exactly 0x6600 (26112) bytes.
 *   - Known TX patches, +25 MHz substitutions, and revision-specific unused
 *     regions are normalized. Changes outside recognized regions are refused
 *     unless the result matches an exact stock SHA-256.
 *   - Unknown revisions, mixed/unrecognized modifications, or corrupt images
 *     are refused rather than guessed at.
 *   - Conversion reconstructs AB00 from the user-supplied recognized source
 *     using verified relocation/copy tables and recalculated operands.
 *   - Source and final output are checked with full-image SHA-256 fingerprints.
 *   - No intermediate firmware image is written.
 *
 * Copyright / distribution intent:
 *   Kenwood firmware is copyrighted. This program contains transformation
 *   metadata, hashes, offsets, and algorithms, but no complete Kenwood firmware
 *   image. Users must supply their own firmware.
 *
 *   Design intent: respect Kenwood's copyright and avoid infringement. This is
 *   a design objective, not a legal determination. This is an independent
 *   project and is not affiliated with or endorsed by Kenwood.
 *
 * IMPORTANT: DO NOT upload Kenwood firmware files, or links to them, to GitHub,
 * including bug reports and discussions.
 */
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include "fwtransmute.h"
#include "fwgrimoire_tk840_9306_8355.h"
#include <stdint.h>
#include <stdlib.h>
#include <string.h>


/* ---- inlined from fwgrimoire.h ---- */
#ifndef FWGRIMOIRE_H
#define FWGRIMOIRE_H

#include <stddef.h>
#include <stdint.h>

#define FW_IMAGE_SIZE 0x6600u
#define FW_CPU_BASE   0x8000u

struct fw_move {
    uint16_t src;
    uint16_t dst;
    uint16_t len;
};

/* 16-bit little-endian absolute firmware address at dst. */
struct fw_reloc16 {
    uint16_t dst;
};

/* Raw-byte positions where CALL/BR auto-relocation must not fire. */
struct fw_abs_skip {
    uint16_t dst;
};

/* Relative branch instruction beginning at dst; operand is derived at runtime. */
struct fw_rel8 {
    uint16_t dst;
};

/* Residual bytes copied from the caller-supplied source image. */
struct fw_overlay {
    uint16_t src;
    uint16_t dst;
    uint16_t len;
};

/* Rebase existing little-endian source pointer tables using relocation shifts.
 * Original words are read from the caller-supplied source firmware.
 * Ranges are inclusive; entries outside them are left for another rule.
 */
struct fw_table_rebase {
    uint16_t src;
    uint16_t dst;
    uint16_t words;
    uint16_t min_addr;
    uint16_t max_addr;
    int16_t delta;
};

/* Copy a real CALL instruction from a corresponding source routine and
 * derive its relocated 16-bit callee address using the existing move map.
 * No target instruction bytes are supplied by this record.
 */
struct fw_call_rebase {
    uint16_t src;
    uint16_t dst;
};

/* Copy a verified existing instruction sequence from the caller's firmware.
 * Unlike an address-rebasing move, this does NOT change source->target
 * address mappings, because the original routine can remain in use.
 */
/* Original absolute BR instructions relocated using the source firmware
 * and address map; no target instruction bytes are embedded in this record.
 */
struct fw_br_rebase {
    uint16_t src;
    uint16_t dst;
};

struct fw_source_extract {
    uint16_t src;
    uint16_t dst;
    uint16_t len;
};

/* Executable source block whose absolute CALL/BR operands are rebased from
 * verified instruction boundaries in the caller's source image.
 * Positions below are relative to the start of the source code block.
 */
struct fw_code_abs_site { uint16_t offset; };
struct fw_code_block {
    uint16_t src;
    uint16_t dst;
    uint16_t len;
    const struct fw_code_abs_site *abs_sites;
    size_t abs_count;
};

/* Form a new CALLT vector from the address of a relocated source routine. */
struct fw_new_callt_vector {
    uint16_t index;
    uint16_t extract_index;
};

/* Invert an existing BNE/BE condition to bypass a newly inserted path.
 * The short branch targets the relocated original fallthrough instruction.
 */
struct fw_cond_invert { uint16_t src; uint16_t dst; };

/* Replace an existing 8-byte inline source helper with the one-byte CALLT
 * reference to the same helper relocated elsewhere from the input firmware.
 */
struct fw_inline_callt { uint16_t src; uint16_t dst; };

/* Rebase a source loop whose inline body has been condensed to CALLT.
 * Its destination is relative to the relocated source function's entry.
 */
struct fw_shortened_loop { uint16_t src; uint16_t dst; uint16_t origin; };

struct fw_transmutation {
    const char *name;
    const char *source_sha256;
    const char *target_sha256;

    const struct fw_move *moves;
    size_t move_count;

    const struct fw_abs_skip *abs_skips;
    size_t abs_skip_count;

    const struct fw_reloc16 *relocs;
    size_t reloc_count;

    const struct fw_rel8 *rel8;
    size_t rel8_count;

    const struct fw_table_rebase *table_rebases;
    size_t table_rebase_count;

    const struct fw_call_rebase *calls;
    size_t call_rebase_count;

    const struct fw_br_rebase *brs;
    size_t br_rebase_count;

    const struct fw_source_extract *extracts;
    size_t extract_count;

    const struct fw_code_block *code_blocks;
    size_t code_block_count;

    const struct fw_overlay *overlays;
    size_t overlay_count;

    const struct fw_new_callt_vector *new_vectors;
    size_t new_vector_count;

    const struct fw_cond_invert *inverted_branches;
    size_t inverted_branch_count;

    const struct fw_inline_callt *inline_callt;
    size_t inline_callt_count;

    const struct fw_shortened_loop *shortened_loops;
    size_t shortened_loop_count;
};

#endif


