/* ---- inlined from fw_normalize.h ---- */
#ifndef FW_NORMALIZE_H
#define FW_NORMALIZE_H

#include <stddef.h>
#include <stdint.h>

#define FW_NORM_SIZE 0x6600u

/* The result records recognized changes; the output is always STOCK firmware. */
struct fw_norm_info {
    const char *revision;
    const char *stock_sha256;
    int conventional_tx_fixed;
    int dealer_tx_fixed;
    unsigned plus25_sites;
    unsigned padding_bytes_removed;
};

/* Return 1 ONLY when the normalized image SHA-256 is an exact known stock hash.
 * Return 0 for ALL unknown revisions, unrecognized patches, mixed, or corrupt
 * states. No output is trusted on failure. Normalization never changes input.
 * shahex must produce lowercase 64-character SHA-256 text + terminator.
 */
int fw_normalize_known(const uint8_t *input, uint8_t *out,
                       struct fw_norm_info *info,
                       void (*shahex)(const uint8_t *, size_t, char[65]));

#endif


/* ---- inlined from fw_normalize.c ---- */
/*
 * TK-940/941 patch normalization, independent of the transmutation engine.
 * Recognize exact code changes and discard contents of verified unused areas.
 * Exact stock SHA-256 verification is the final authority.
 *
 * Do not add wildcard/fuzzy recognition: another patch implementation is
 * unsupported even if it appears to do the same thing.
 */
#include <string.h>

#define CPU2OFF(x) ((x) - 0x8000u)

struct norm_revision {
    const char *name;
    const char *sha;
    uint16_t tx_addr;
    uint16_t dealer_addr;
    uint16_t plus25_addr[3];
    uint16_t trailing_padding_start;
    uint8_t stock_tx[16];
    uint8_t fixed_tx[16];
};

/* Exact positions and patched 16-byte instructions verified against
 * original, user-supplied firmware images.
 */
