static const uint8_t b5ec_tx_alternate[16] = {
    0x28,0x9a,0xde,0x83,0x29,0x60,0x03,0x00,0x88,0xe8,0x59,0x24,0x01,0x5d,0x03,0x9f
};
static const uint8_t stock_dealer_template[15] = {
    0x28,0,0,0x24,0xc8,0x58,0x24,0x01,0x5c,0x03,0x9f,0x08,0xa4,0x78,0x0a
};
static const uint8_t fixed_dealer_template[15] = {
    0x28,0,0,0x24,0xc8,0x46,0x46,0x58,0x24,0x01,0x5c,0x03,0x9f,0x14,0x13
};
/* Historical +25 MHz firmware modifications have two recognized layouts:
   an immediate-only substitution and a variant that also NOPs the following
   instruction. Every supported stock image has the same seven stock bytes
   at all three sites. */
static const uint8_t stock_25[7]={0x2d,0xc0,0xfd,0x1a,0x20,0x82,0x05};
static const uint8_t patched_25_short[7]={0x2d,0x20,0x02,0x1a,0x20,0x82,0x05};
static const uint8_t patched_25_full[7]={0x2d,0x20,0x02,0x1a,0x20,0x00,0x00};
static int normalize_plus25(uint8_t *site)
{
    if(!memcmp(site,stock_25,7))return 0;
    if(memcmp(site,patched_25_short,7) &&
       memcmp(site,patched_25_full,7))return -1;
    memcpy(site,stock_25,7);
    return 1;
}
static int normalize_for_revision(const uint8_t *in, uint8_t *out,
                                  const struct norm_revision *r,
                                  struct fw_norm_info *info,
                                  void (*shahex)(const uint8_t *, size_t, char[65]))
{
    uint8_t orig_dealer[15], fixed_dealer[15];
    char hash[65];
    unsigned i;
    size_t tx=CPU2OFF(r->tx_addr), dealer=CPU2OFF(r->dealer_addr);
    struct fw_norm_info result;
    memset(&result,0,sizeof(result));
    result.revision=r->name;
    result.stock_sha256=r->sha;
    memcpy(out,in,FW_NORM_SIZE);

    if(!memcmp(out+tx,r->stock_tx,16)) {
        /* Already stock. */
    } else if (!memcmp(out+tx,r->fixed_tx,16)) {
        memcpy(out+tx,r->stock_tx,16);
        result.conventional_tx_fixed=1;
    } else if (r->tx_addr==0x9c6e && !memcmp(out+tx,b5ec_tx_alternate,16)) {
        memcpy(out+tx,r->stock_tx,16);
        result.conventional_tx_fixed=1;
    } else return 0;

    memcpy(orig_dealer,stock_dealer_template,sizeof(orig_dealer));
    memcpy(fixed_dealer,fixed_dealer_template,sizeof(fixed_dealer));
    /* Preserve the stock CALL target: unlike the patch body it is unchanged. */
    orig_dealer[1]=fixed_dealer[1]=in[dealer+1];
    orig_dealer[2]=fixed_dealer[2]=in[dealer+2];
    if(!memcmp(out+dealer,orig_dealer,15)) {
        /* Already stock. */
    } else if(!memcmp(out+dealer,fixed_dealer,15)) {
        memcpy(out+dealer,orig_dealer,15);
        result.dealer_tx_fixed=1;
    } else return 0;

    for(i=0;i<3;i++) {
        size_t p=CPU2OFF(r->plus25_addr[i]);
        int change=normalize_plus25(out+p);
        if(change<0)return 0;
        if(change)result.plus25_sites++;
    }

    /* Clear revision-specific unused space, including any annotations,
     * feature flags, or extra code stored in the erased regions. No author
     * marking needs to be identified. Preserve the original identification
     * block at 0x6580..0x65BE. Full stock SHA-256 verification rejects any
     * changes outside these regions and the recognized code patches.
     */
    {
        size_t p;
        for (p = r->trailing_padding_start; p <= 0x657f; p++) {
            if (out[p] != 0xff) {
                out[p] = 0xff;
                result.padding_bytes_removed++;
            }
        }
        for (p = 0x65bf; p < FW_NORM_SIZE; p++) {
            if (out[p] != 0xff) {
                out[p] = 0xff;
                result.padding_bytes_removed++;
            }
        }
    }
    shahex(out,FW_NORM_SIZE,hash);
    if(strcmp(hash,r->sha)) return 0;
    if(info) *info=result;
    return 1;
}

int fw_normalize_known(const uint8_t *input, uint8_t *out,
                       struct fw_norm_info *info,
                       void (*shahex)(const uint8_t *, size_t, char[65]))
{
    size_t i;
    if(!input || !out || !shahex || input == out) return 0;
    for(i=0;i<sizeof(revs)/sizeof(revs[0]);i++) {
        if(normalize_for_revision(input,out,&revs[i],info,shahex)) return 1;
    }
    return 0;
}


typedef struct {
    uint32_t h[8];
    uint64_t bits;
    uint8_t buf[64];
    size_t used;
} sha256_ctx;

static uint32_t rotr32(uint32_t x, unsigned n) { return (x >> n) | (x << (32 - n)); }
static uint32_t be32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}
static void put_be32(uint8_t *p, uint32_t x) {
    p[0]=(uint8_t)(x>>24); p[1]=(uint8_t)(x>>16); p[2]=(uint8_t)(x>>8); p[3]=(uint8_t)x;
}
static void sha256_block(sha256_ctx *c, const uint8_t b[64]) {
    static const uint32_t k[64] = {
        0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
        0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
        0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
        0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
        0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
        0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
        0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
        0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
    };
    uint32_t w[64],a,d,e,f,g,h,t1,t2,bb,cc;
    unsigned i;
    for(i=0;i<16;i++) w[i]=be32(b+4*i);
    for(i=16;i<64;i++) {
        uint32_t s0=rotr32(w[i-15],7)^rotr32(w[i-15],18)^(w[i-15]>>3);
        uint32_t s1=rotr32(w[i-2],17)^rotr32(w[i-2],19)^(w[i-2]>>10);
        w[i]=w[i-16]+s0+w[i-7]+s1;
    }
    a=c->h[0]; bb=c->h[1]; cc=c->h[2]; d=c->h[3]; e=c->h[4]; f=c->h[5]; g=c->h[6]; h=c->h[7];
    for(i=0;i<64;i++) {
        uint32_t S1=rotr32(e,6)^rotr32(e,11)^rotr32(e,25);
        uint32_t ch=(e&f)^((~e)&g);
        uint32_t S0=rotr32(a,2)^rotr32(a,13)^rotr32(a,22);
        uint32_t maj=(a&bb)^(a&cc)^(bb&cc);
        t1=h+S1+ch+k[i]+w[i]; t2=S0+maj;
        h=g; g=f; f=e; e=d+t1; d=cc; cc=bb; bb=a; a=t1+t2;
    }
    c->h[0]+=a; c->h[1]+=bb; c->h[2]+=cc; c->h[3]+=d;
    c->h[4]+=e; c->h[5]+=f; c->h[6]+=g; c->h[7]+=h;
}
static void sha256_init(sha256_ctx *c) {
    static const uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    memcpy(c->h,iv,sizeof(iv)); c->bits=0; c->used=0;
}
static void sha256_update(sha256_ctx *c,const void *vp,size_t n) {
    const uint8_t *p=(const uint8_t*)vp; c->bits += (uint64_t)n*8;
    while(n) {
        size_t take=64-c->used; if(take>n) take=n;
        memcpy(c->buf+c->used,p,take); c->used+=take; p+=take; n-=take;
        if(c->used==64) { sha256_block(c,c->buf); c->used=0; }
    }
}
static void sha256_final(sha256_ctx *c,uint8_t out[32]) {
    uint64_t bits=c->bits; unsigned i;
    c->buf[c->used++]=0x80;
    if(c->used>56) { while(c->used<64)c->buf[c->used++]=0; sha256_block(c,c->buf); c->used=0; }
    while(c->used<56)c->buf[c->used++]=0;
    for(i=0;i<8;i++) c->buf[63-i]=(uint8_t)(bits>>(8*i));
    sha256_block(c,c->buf);
    for(i=0;i<8;i++) put_be32(out+4*i,c->h[i]);
}
static void sha256_bytes(const uint8_t *p,size_t n,uint8_t out[32]) { sha256_ctx c; sha256_init(&c); sha256_update(&c,p,n); sha256_final(&c,out); }
static void hex32(const uint8_t d[32],char out[65]) {
    static const char h[]="0123456789abcdef"; unsigned i;
    for(i=0;i<32;i++){out[2*i]=h[d[i]>>4];out[2*i+1]=h[d[i]&15];} out[64]=0;
}



static void fw_norm_shahex(const uint8_t *p, size_t n, char out[65])
{
    uint8_t digest[32];
    sha256_bytes(p,n,digest);
    hex32(digest,out);
}



static int sha256_matches(const uint8_t *buf, size_t n, const char *expected,
                          char actual[65])
{
    uint8_t digest[32];
    sha256_bytes(buf, n, digest);
    hex32(digest, actual);
    return strcmp(actual, expected) == 0;
}

static int map_source_address(const struct fw_transmutation *r, uint16_t old_addr,
                              uint16_t *new_addr)
{
    size_t i;
    uint32_t off;

    if (old_addr < FW_CPU_BASE)
        return -1;
    off = (uint32_t)old_addr - FW_CPU_BASE;
    if (off >= FW_IMAGE_SIZE)
        return -1;

    for (i = 0; i < r->move_count; i++) {
        const struct fw_move *m = &r->moves[i];
        if (off >= m->src && off < (uint32_t)m->src + m->len) {
            uint32_t mapped = FW_CPU_BASE + m->dst + (off - m->src);
            if (mapped > 0xFFFFu)
                return -1;
            *new_addr = (uint16_t)mapped;
            return 0;
        }
    }

    /* Bytes not explicitly moved retain their source address. */
    *new_addr = old_addr;
    return 0;
}

static int inverse_destination_offset(const struct fw_transmutation *r,
                                      uint16_t dst, uint16_t *src)
{
    size_t i = r->move_count;
    while (i--) {
        const struct fw_move *m = &r->moves[i];
        if (dst >= m->dst && dst < (uint32_t)m->dst + m->len) {
            *src = (uint16_t)(m->src + (dst - m->dst));
            return 0;
        }
    }
    *src = dst;
    return 0;
}

static int branch_form(const uint8_t *p, size_t remain,
                       unsigned *ilen, unsigned *disp_index)
{
    uint8_t op, b1;
    if (!remain) return -1;
    op = p[0];
    if (op == 0x14 || op == 0x80 || op == 0x81 || op == 0x82 || op == 0x83) {
        if (remain < 2) return -1;
        *ilen = 2; *disp_index = 1; return 0;
    }
    if (op >= 0x70 && op <= 0x77) {
        if (remain < 3) return -1;
        *ilen = 3; *disp_index = 2; return 0;
    }
    if ((op == 0x02 || op == 0x03) && remain >= 3) {
        b1 = p[1];
        if ((b1 >= 0xA0 && b1 <= 0xAF) || (b1 >= 0xB8 && b1 <= 0xBF)) {
            *ilen = 3; *disp_index = 2; return 0;
        }
    }
    if (op == 0x07 && remain >= 3 && (p[1] == 0xFC || p[1] == 0xFD)) {
        *ilen = 3; *disp_index = 2; return 0;
    }
    if (op == 0x08 && remain >= 4) {
        b1 = p[1];
        if ((b1 >= 0xA0 && b1 <= 0xAF) || b1 == 0xD5 || b1 == 0xBE || b1 == 0xBF) {
            *ilen = 4; *disp_index = 3; return 0;
        }
    }
    return -1;
}

static int abs_scan_is_skipped(const struct fw_transmutation *r, uint16_t dst)
{
    size_t i;
    for (i = 0; i < r->abs_skip_count; i++)
        if (r->abs_skips[i].dst == dst)
            return 1;
    return 0;
}

static int apply_transmutation(const struct fw_transmutation *r, const uint8_t *src,
                        uint8_t *out)
{
    size_t i;

    /* Unmoved bytes keep their original offsets; moved regions are selected
     * by the conversion table for the source revision.
     */
    memcpy(out, src, FW_IMAGE_SIZE);

    for (i = 0; i < r->move_count; i++) {
        const struct fw_move *m = &r->moves[i];
        if ((uint32_t)m->src + m->len > FW_IMAGE_SIZE ||
            (uint32_t)m->dst + m->len > FW_IMAGE_SIZE) {
            fprintf(stderr, "Transmutation move %zu is out of bounds\n", i);
            return -1;
        }
        memcpy(out + m->dst, src + m->src, m->len);
    }

    /*
     * Most absolute firmware references are operands of CALL (0x28) or
     * absolute BR (0x2C). Relocate these generically. The grimoire stores only
     * byte locations that must be excluded from the instruction scan.
     */
    for (i = 0; i + 2 < FW_IMAGE_SIZE; i++) {
        uint16_t old_addr, new_addr;
        if (out[i] != 0x28 && out[i] != 0x2C)
            continue;
        if (abs_scan_is_skipped(r, (uint16_t)i))
            continue;
        old_addr = (uint16_t)(out[i + 1] | ((uint16_t)out[i + 2] << 8));
        if (old_addr < FW_CPU_BASE || old_addr >= FW_CPU_BASE + FW_IMAGE_SIZE)
            continue;
        if (map_source_address(r, old_addr, &new_addr) < 0 || new_addr == old_addr)
            continue;
        out[i + 1] = (uint8_t)new_addr;
        out[i + 2] = (uint8_t)(new_addr >> 8);
    }

    /*
     * Unusual 16-bit little-endian firmware references not handled by the
     * generic CALL/BR pass. These locations still contain no replacement word;
     * the new address is derived from the move map.
     */
    for (i = 0; i < r->reloc_count; i++) {
        uint32_t d = r->relocs[i].dst;
        uint16_t old_addr, new_addr;
        if (d + 1 >= FW_IMAGE_SIZE) {
            fprintf(stderr, "Transmutation reloc %zu is out of bounds\n", i);
            return -1;
        }
        old_addr = (uint16_t)(out[d] | ((uint16_t)out[d + 1] << 8));
        if (map_source_address(r, old_addr, &new_addr) < 0) {
            fprintf(stderr,
                    "Transmutation reloc %zu at 0x%04X cannot map address 0x%04X\n",
                    i, (unsigned)d, old_addr);
            return -1;
        }
        out[d] = (uint8_t)new_addr;
        out[d + 1] = (uint8_t)(new_addr >> 8);
    }

    /*
     * Relative branch displacements are derived from the old branch target,
     * the move map, and the branch's new location. The grimoire stores only
     * the instruction location, never the target displacement byte.
     */
    for (i = 0; i < r->rel8_count; i++) {
        uint16_t d = r->rel8[i].dst;
        uint16_t s_off, old_target_off, new_target_addr;
        unsigned ilen, disp_index;
        int8_t old_disp;
        int32_t new_disp;

        if (d >= FW_IMAGE_SIZE ||
            inverse_destination_offset(r, d, &s_off) < 0 ||
            s_off >= FW_IMAGE_SIZE ||
            branch_form(src + s_off, FW_IMAGE_SIZE - s_off, &ilen, &disp_index) < 0 ||
            (uint32_t)s_off + ilen > FW_IMAGE_SIZE ||
            (uint32_t)d + ilen > FW_IMAGE_SIZE) {
            fprintf(stderr, "Transmutation rel8 %zu is invalid\n", i);
            return -1;
        }

        old_disp = (int8_t)src[s_off + disp_index];
        if ((int32_t)s_off + (int32_t)ilen + old_disp < 0 ||
            (int32_t)s_off + (int32_t)ilen + old_disp >= (int32_t)FW_IMAGE_SIZE) {
            fprintf(stderr, "Transmutation rel8 %zu target is out of bounds\n", i);
            return -1;
        }
        old_target_off = (uint16_t)((int32_t)s_off + (int32_t)ilen + old_disp);
        if (map_source_address(r, (uint16_t)(FW_CPU_BASE + old_target_off),
                               &new_target_addr) < 0) {
            fprintf(stderr, "Transmutation rel8 %zu cannot map target\n", i);
            return -1;
        }
        new_disp = (int32_t)new_target_addr -
                   (int32_t)(FW_CPU_BASE + d + ilen);
        if (new_disp < -128 || new_disp > 127) {
            fprintf(stderr, "Transmutation rel8 %zu displacement overflow\n", i);
            return -1;
        }
        out[d + disp_index] = (uint8_t)(int8_t)new_disp;
    }

    /*
     * Rebase source pointer tables as data, not executable instructions.
     * B5EC jump and dispatch tables derive their entries from the relocated
     * source routines. Compute the new pointers rather than hardcoding them.
     */
    for (i = 0; i < r->table_rebase_count; i++) {
        const struct fw_table_rebase *t = &r->table_rebases[i];
        size_t j;
        if ((uint32_t)t->src + (uint32_t)t->words * 2 > FW_IMAGE_SIZE ||
            (uint32_t)t->dst + (uint32_t)t->words * 2 > FW_IMAGE_SIZE ||
            t->min_addr > t->max_addr) {
            fprintf(stderr, "Transmutation table rebasing %zu is invalid\n", i);
            return -1;
        }
        for (j = 0; j < t->words; j++) {
            uint32_t s = (uint32_t)t->src + j * 2;
            uint32_t d = (uint32_t)t->dst + j * 2;
            uint16_t old_addr = (uint16_t)(src[s] | ((uint16_t)src[s + 1] << 8));
            int32_t next_addr;
            if (old_addr < t->min_addr || old_addr > t->max_addr)
                continue;
            next_addr = (int32_t)old_addr + t->delta;
            if (next_addr < (int32_t)FW_CPU_BASE || next_addr >= (int32_t)(FW_CPU_BASE + FW_IMAGE_SIZE)) {
                fprintf(stderr, "Transmutation table address out of range at %zu\n", i);
                return -1;
            }
            out[d] = (uint8_t)next_addr;
            out[d + 1] = (uint8_t)(next_addr >> 8);
        }
    }

    /* Copy source CALL instructions and relocate their 16-bit operands
     * using the source-revision address map.
     */
    for (i = 0; i < r->call_rebase_count; i++) {
        const struct fw_call_rebase *c = &r->calls[i];
        uint16_t old_addr, new_addr;
        if ((uint32_t)c->src + 3 > FW_IMAGE_SIZE ||
            (uint32_t)c->dst + 3 > FW_IMAGE_SIZE ||
            src[c->src] != 0x28) {
            fprintf(stderr, "Transmutation CALL rebasing %zu is invalid\n", i);
            return -1;
        }
        old_addr = (uint16_t)(src[c->src + 1] | ((uint16_t)src[c->src + 2] << 8));
        if (map_source_address(r, old_addr, &new_addr) < 0) {
            fprintf(stderr, "Transmutation CALL %zu cannot map callee\n", i);
            return -1;
        }
        out[c->dst] = src[c->src];
        out[c->dst + 1] = (uint8_t)new_addr;
        out[c->dst + 2] = (uint8_t)(new_addr >> 8);
    }

    /* Copy source absolute BR instructions and derive their relocated targets
     * using the source-revision address map.
     */
    for (i = 0; i < r->br_rebase_count; i++) {
        const struct fw_br_rebase *b = &r->brs[i];
        uint16_t old_addr, new_addr;
        if ((uint32_t)b->src + 3 > FW_IMAGE_SIZE ||
            (uint32_t)b->dst + 3 > FW_IMAGE_SIZE ||
            src[b->src] != 0x2C) {
            fprintf(stderr, "Transmutation BR rebasing %zu is invalid\n", i);
            return -1;
        }
        old_addr = (uint16_t)(src[b->src+1] | ((uint16_t)src[b->src+2] << 8));
        if (map_source_address(r, old_addr, &new_addr) < 0) {
            fprintf(stderr, "Transmutation BR %zu cannot map target\n", i);
            return -1;
        }
        out[b->dst] = src[b->src];
        out[b->dst+1] = (uint8_t)new_addr;
        out[b->dst+2] = (uint8_t)(new_addr >> 8);
    }

    /* Copy identified instruction sequences from the input firmware.
     * These copies do not change the address map.
     */
    for (i = 0; i < r->extract_count; i++) {
        const struct fw_source_extract *e = &r->extracts[i];
        if (!e->len || (uint32_t)e->src + e->len > FW_IMAGE_SIZE ||
            (uint32_t)e->dst + e->len > FW_IMAGE_SIZE) {
            fprintf(stderr, "Transmutation source extraction %zu is invalid\n", i);
            return -1;        }
        memcpy(out + e->dst, src + e->src, e->len);
    }

    /* Copy an existing executable block and relocate only confirmed absolute
     * CALL/BR instruction operands. The source and callee addresses come
     * from the supplied original image and the preexisting move map.
     * Site positions were established by disassembly, not a raw opcode scan.
     */
    for (i = 0; i < r->code_block_count; i++) {
        const struct fw_code_block *b = &r->code_blocks[i];
        size_t j;
        if (!b->len || (uint32_t)b->src + b->len > FW_IMAGE_SIZE ||
            (uint32_t)b->dst + b->len > FW_IMAGE_SIZE) {
            fprintf(stderr, "Code block %zu invalid\n", i);
            return -1;
        }
        memcpy(out + b->dst, src + b->src, b->len);
        for (j = 0; j < b->abs_count; j++) {
            uint16_t off = b->abs_sites[j].offset;
            uint32_t s = (uint32_t)b->src + off;
            uint32_t d = (uint32_t)b->dst + off;
            uint16_t old_addr, new_addr;
            if (off + 3 > b->len || (src[s] != 0x28 && src[s] != 0x2C)) {
                fprintf(stderr, "Code block %zu CALL/BR site %zu invalid\n", i, j);
                return -1;
            }
            old_addr = (uint16_t)(src[s+1] | (uint16_t)src[s+2] << 8);
            if (map_source_address(r, old_addr, &new_addr) < 0) {
                fprintf(stderr, "Code block %zu CALL/BR site %zu cannot map target\n", i, j);
                return -1;
            }
            out[d+1] = (uint8_t)new_addr;
            out[d+2] = (uint8_t)(new_addr >> 8);
        }
    }

    /* Connect an unused source CALLT slot to a helper whose instructions
     * were already extracted from the user's firmware. The vector address
     * is computed from the extraction destination.
     */
    for (i = 0; i < r->new_vector_count; i++) {
        const struct fw_new_callt_vector *v = &r->new_vectors[i];
        uint32_t d, target;
        if (v->index >= 32 || v->extract_index >= r->extract_count) {
            fprintf(stderr, "New CALLT vector %zu has invalid index\n", i);
            return -1;
        }
        d = 0x40u + (uint32_t)v->index * 2;
        target = FW_CPU_BASE + r->extracts[v->extract_index].dst;
        if (d + 2 > FW_IMAGE_SIZE || target >= FW_CPU_BASE + FW_IMAGE_SIZE ||
            src[d] != 0xFF || src[d + 1] != 0xFF) {
            fprintf(stderr, "New CALLT vector %zu is not an erased source slot\n", i);
            return -1;
        }
        out[d] = (uint8_t)target;
        out[d + 1] = (uint8_t)(target >> 8);
    }

    /* Invert source BNE/BE and branch to the relocation of the original
     * fallthrough. This is the documented code-path split around 0x47EA,
     * not a general-purpose opcode substitution.
     */
    for (i = 0; i < r->inverted_branch_count; i++) {
        const struct fw_cond_invert *b = &r->inverted_branches[i];
        uint16_t new_target;
        int32_t displacement;
        if ((uint32_t)b->src + 2 > FW_IMAGE_SIZE ||
            (uint32_t)b->dst + 2 > FW_IMAGE_SIZE ||
            (src[b->src] != 0x80 && src[b->src] != 0x81)) {
            fprintf(stderr, "Inverted branch %zu is invalid\n", i);
            return -1;
        }
        if (map_source_address(r, (uint16_t)(FW_CPU_BASE + b->src + 2), &new_target) < 0) {
            fprintf(stderr, "Inverted branch %zu cannot map fallthrough\n", i);
            return -1;
        }
        displacement = (int32_t)new_target - (FW_CPU_BASE + b->dst + 2);
        if (displacement < -128 || displacement > 127) {
            fprintf(stderr, "Inverted branch %zu displacement overflow\n", i);
            return -1;
        }
        out[b->dst] = (uint8_t)(src[b->src] ^ 0x01);
        out[b->dst + 1] = (uint8_t)(int8_t)displacement;
    }

    /* AB00 factors one source 8-byte pair of register writes into the
     * already extracted helper. Every listed original site must contain
     * exactly the same user-supplied source instructions; we synthesize the
     * NEC78K/III CALLT opcode from the linked vector index.
     */
    for (i = 0; i < r->inline_callt_count; i++) {
        const struct fw_inline_callt *site = &r->inline_callt[i];
        const struct fw_new_callt_vector *vector;
        const struct fw_source_extract *helper;
        if (r->new_vector_count < 1) {
            fprintf(stderr, "Inline CALLT lacks helper vector\n");
            return -1;
        }
        vector = &r->new_vectors[0];
        if (vector->index >= 32 || vector->extract_index >= r->extract_count) {
            fprintf(stderr, "Inline CALLT helper index invalid\n");
            return -1;
        }
        helper = &r->extracts[vector->extract_index];
        if (helper->len != 8 ||
            (uint32_t)site->src + helper->len > FW_IMAGE_SIZE ||
            site->dst >= FW_IMAGE_SIZE ||
            (uint32_t)helper->src + helper->len > FW_IMAGE_SIZE ||
            memcmp(src + site->src, src + helper->src, helper->len) != 0) {
            fprintf(stderr, "Inline CALLT %zu does not contain source helper\n", i);
            return -1;
        }
        out[site->dst] = (uint8_t)(0xE0u + vector->index);
        /* When an original four-byte BF loops back over the inline
         * eight-byte helper, reuse that BF instruction and derive its new
         * displacement to the one-byte CALLT. The condition must target
         * the exact original helper entry; unrelated bit tests are ignored.
         */
        if ((uint32_t)site->src + 12 <= FW_IMAGE_SIZE &&
            (uint32_t)site->dst + 5 <= FW_IMAGE_SIZE &&
            src[site->src + 8] == 0x08 &&
            (src[site->src + 9] & 0xF0) == 0xA0 &&
            (int32_t)site->src + 12 + (int8_t)src[site->src + 11] == site->src) {
            memcpy(out + site->dst + 1, src + site->src + 8, 3);
            out[site->dst + 4] = (uint8_t)(int8_t)
                ((int32_t)site->dst - ((int32_t)site->dst + 5));
        }
    }


    /* The dispatcher at source 0xC187 is shortened by 7 bytes when its
     * inline helper becomes CALLT. Rebase the loop to its original prefix,
     * using the relocated function entry and original source branch target.
     */
    for (i = 0; i < r->shortened_loop_count; i++) {
        const struct fw_shortened_loop *b = &r->shortened_loops[i];
        uint16_t origin_addr;
        int32_t old_target, new_target, disp;
        if ((uint32_t)b->src + 2 > FW_IMAGE_SIZE ||
            (uint32_t)b->dst + 2 > FW_IMAGE_SIZE ||
            b->origin >= b->src ||
            (src[b->src] != 0x80 && src[b->src] != 0x81 &&
             src[b->src] != 0x82 && src[b->src] != 0x83)) {
            fprintf(stderr, "Shortened-loop branch %zu is invalid\n", i);
            return -1;
        }
        old_target = (int32_t)b->src + 2 + (int8_t)src[b->src + 1];
        if (old_target < b->origin || old_target > b->origin + 16 ||
            map_source_address(r, (uint16_t)(FW_CPU_BASE + b->origin), &origin_addr) < 0) {
            fprintf(stderr, "Shortened-loop branch %zu cannot map loop start\n", i);
            return -1;
        }
        new_target = (int32_t)origin_addr + (old_target - b->origin);
        disp = new_target - (FW_CPU_BASE + b->dst + 2);
        if (disp < -128 || disp > 127) {
            fprintf(stderr, "Shortened-loop branch %zu displacement overflow\n", i);
            return -1;
        }
        out[b->dst] = src[b->src];
        out[b->dst + 1] = (uint8_t)(int8_t)disp;
    }

    /* Copy remaining output spans from source offsets selected by comparing
     * the verified source and target revisions. Short spans are permitted.
     */
    for (i = 0; i < r->overlay_count; i++) {
        const struct fw_overlay *o = &r->overlays[i];
        if ((uint32_t)o->src + o->len > FW_IMAGE_SIZE ||
            (uint32_t)o->dst + o->len > FW_IMAGE_SIZE) {
            fprintf(stderr, "Transmutation source-copy %zu is out of bounds\n", i);
            return -1;
        }
        memcpy(out + o->dst, src + o->src, o->len);
    }

    return 0;
}

static const struct fw_transmutation *const GRIMOIRE[] = {
    &FW_TRANSMUTATION_B5EC_AB00,
    &FW_TRANSMUTATION_REV2CCA_AB00,
    &FW_TRANSMUTATION_T_8E9D_TO_AB00
};

#define GRIMOIRE_COUNT (sizeof(GRIMOIRE) / sizeof(GRIMOIRE[0]))
#define AB00_SHA256 "45e9e8cfb4070fd14a9c6339f97cd19140faf4acf145dc043a9e78c3e8757bcf"

static const struct fw_transmutation *find_transmutation(const char *source_hash)
{
    size_t i;
    for (i = 0; i < GRIMOIRE_COUNT; i++)
        if (strcmp(source_hash, GRIMOIRE[i]->source_sha256) == 0)
            return GRIMOIRE[i];
    return NULL;
}




 
/* Transmutation requires known input, verifies the source stock hash,
   validates each conversion stage, and verifies AB00 before committing output. */
struct tot_patch_region {
    uint16_t address;
    size_t length;
    uint8_t original[48];
    uint8_t modified[48];
};
